// HMAC-SHA256 signature verification on raw body, opt-in, with replay-window check.
// Headers required when WEBHOOK_INTEGRITY_CHECK_ENABLED=1:
//   x-csv-signature: <hex-hmac-sha256(timestamp + '.' + rawBody)>
//   x-csv-timestamp: <unix-seconds>
// Enable by setting CSV_UPLOAD_SIGNING_SECRET + WEBHOOK_INTEGRITY_CHECK_ENABLED=1.
//
// Replay-window default 5 min. Override with CSV_UPLOAD_REPLAY_WINDOW_S.

const secret = $env.CSV_UPLOAD_SIGNING_SECRET;
const integrityCheckEnabled = $env.WEBHOOK_INTEGRITY_CHECK_ENABLED === '1';

if (!secret || !integrityCheckEnabled) {
  return [$input.first()];
}

const crypto = require('crypto');
const item = $input.first();
const rawBody = item.rawBody || (typeof item.body === 'string' ? item.body : JSON.stringify(item.body || {}));
const headers = item.headers || {};
const providedSig = headers['x-csv-signature'] || headers['X-CSV-Signature'];
const tsHeader = headers['x-csv-timestamp'] || headers['X-CSV-Timestamp'];

if (!providedSig || typeof providedSig !== 'string') {
  throw new Error('UNAUTHORIZED: missing x-csv-signature header');
}
if (!tsHeader || typeof tsHeader !== 'string') {
  throw new Error('UNAUTHORIZED: missing x-csv-timestamp header (replay protection)');
}

const tsNum = parseInt(tsHeader, 10);
if (!Number.isFinite(tsNum)) {
  throw new Error('UNAUTHORIZED: invalid x-csv-timestamp value');
}
const nowSec = Math.floor(Date.now() / 1000);
const REPLAY_WINDOW_S = parseInt($env.CSV_UPLOAD_REPLAY_WINDOW_S || '300', 10);
if (Math.abs(nowSec - tsNum) > REPLAY_WINDOW_S) {
  throw new Error('UNAUTHORIZED: timestamp outside replay window (' + REPLAY_WINDOW_S + 's)');
}

const signedPayload = tsHeader + '.' + rawBody;
const expected = crypto.createHmac('sha256', secret).update(signedPayload, 'utf8').digest('hex');

if (providedSig.length !== expected.length) {
  throw new Error('UNAUTHORIZED: signature length mismatch');
}

const expBuf = Buffer.from(expected, 'utf8');
const provBuf = Buffer.from(providedSig, 'utf8');
if (!crypto.timingSafeEqual(expBuf, provBuf)) {
  throw new Error('UNAUTHORIZED: invalid signature');
}

return [$input.first()];

// Per-IP sliding-window rate limit, opt-in.

if ($env.RATE_LIMIT_ENABLED !== '1') {
  return [$input.first()];
}

const LIMIT = 60;
const WINDOW_MS = 5 * 60 * 1000;
const MAX_KEYS = 5000;

const item = $input.first();
const headers = item.headers || {};
const rawIp = headers['x-forwarded-for'] || headers['x-real-ip'] || 'unknown';
const key = String(rawIp).split(',')[0].trim();

const data = $getWorkflowStaticData('global');
data.rateBuckets = data.rateBuckets || {};
const buckets = data.rateBuckets;
const now = Date.now();

for (const k of Object.keys(buckets)) {
  buckets[k] = (buckets[k] || []).filter(t => now - t < WINDOW_MS);
  if (buckets[k].length === 0) delete buckets[k];
}
if (Object.keys(buckets).length > MAX_KEYS) {
  const oldest = Object.entries(buckets).sort((a, b) => (a[1][0] || 0) - (b[1][0] || 0)).slice(0, 100);
  for (const [k] of oldest) delete buckets[k];
}

const hits = buckets[key] || [];
if (hits.length >= LIMIT) {
  throw new Error('RATE_LIMIT_EXCEEDED: ' + LIMIT + ' requests per ' + Math.round(WINDOW_MS / 60000) + ' minutes for ' + key);
}
buckets[key] = [...hits, now];

return [$input.first()];

// 5-minute idempotency window on sha256(rawBody), opt-in.

const crypto = require('crypto');

if ($env.IDEMPOTENCY_ENABLED !== '1') {
  return [$input.first()];
}

const WINDOW_MS = 5 * 60 * 1000;
const MAX_KEYS = 5000;

const item = $input.first();
const rawBody = item.rawBody || (typeof item.body === 'string' ? item.body : JSON.stringify(item.body || {}));
const dedupKey = crypto.createHash('sha256').update(rawBody, 'utf8').digest('hex').slice(0, 32);

const data = $getWorkflowStaticData('global');
data.seenKeys = data.seenKeys || {};
const seen = data.seenKeys;
const now = Date.now();

for (const k of Object.keys(seen)) {
  if (now - seen[k] > WINDOW_MS) delete seen[k];
}
if (Object.keys(seen).length > MAX_KEYS) {
  const oldest = Object.entries(seen).sort((a, b) => a[1] - b[1]).slice(0, 500);
  for (const [k] of oldest) delete seen[k];
}

if (seen[dedupKey]) {
  return [{ json: { skipped: true, reason: 'duplicate', dedupKey } }];
}
seen[dedupKey] = now;

return [$input.first()];

// Redis variant for clustered n8n:
// const result = await redis.set('csv-idem:' + dedupKey, '1', 'EX', 300, 'NX');
// if (result === null) return [];

// Quote-aware CSV parser. Handles quoted fields with embedded commas, embedded newlines,
// escaped quotes (RFC 4180). BOM stripping. Configurable delimiter.
//
// Hard MAX_BODY_BYTES cap as defense against accidental giant uploads.

const item = $input.first();
const rawBody = item.rawBody || (typeof item.body === 'string' ? item.body : '');
if (typeof rawBody !== 'string') {
  throw new Error('CSV body must be a string. Set Webhook node Options -> Raw Body = true.');
}

const MAX_BODY_BYTES = parseInt($env.MAX_BODY_BYTES || '5242880', 10);
if (Buffer.byteLength(rawBody, 'utf8') > MAX_BODY_BYTES) {
  throw new Error('PAYLOAD_TOO_LARGE: body exceeds MAX_BODY_BYTES=' + MAX_BODY_BYTES);
}

const MAX_ROWS = parseInt($env.MAX_ROWS || '10000', 10);
const delimRaw = $env.CSV_DELIMITER || ',';
const delim = delimRaw === '\\t' ? '\t' : delimRaw;

// Strip BOM
let text = rawBody.charCodeAt(0) === 0xFEFF ? rawBody.slice(1) : rawBody;

// Quote-aware tokenizer
const rows = [];
let field = '';
let row = [];
let inQuotes = false;
for (let i = 0; i < text.length; i++) {
  const c = text[i];
  if (inQuotes) {
    if (c === '"') {
      if (text[i + 1] === '"') { field += '"'; i++; }
      else { inQuotes = false; }
    } else {
      field += c;
    }
  } else {
    if (c === '"') { inQuotes = true; }
    else if (c === delim) { row.push(field); field = ''; }
    else if (c === '\r') { /* skip CR */ }
    else if (c === '\n') { row.push(field); rows.push(row); row = []; field = ''; if (rows.length > MAX_ROWS + 1) break; }
    else { field += c; }
  }
}
// Tail handling
if (field.length > 0 || row.length > 0) { row.push(field); rows.push(row); }

if (rows.length === 0) throw new Error('CSV is empty');
if (rows.length - 1 > MAX_ROWS) throw new Error('TOO_MANY_ROWS: limit is ' + MAX_ROWS);

const headers = rows[0].map(h => String(h || '').trim());
const dataRows = rows.slice(1);

const out = [];
for (let r = 0; r < dataRows.length; r++) {
  const cells = dataRows[r];
  if (cells.length === 1 && cells[0] === '') continue; // skip blank line
  const obj = {};
  for (let c = 0; c < headers.length; c++) {
    obj[headers[c]] = cells[c] != null ? cells[c] : '';
  }
  out.push({ json: { rowNumber: r + 2, raw: obj } }); // +2 because header is row 1, data starts at row 2
}
return out;

// Validate + sanitize each row against VALIDATION_SCHEMA env JSON.
// Schema shape (see README for details):
// { columns: [{ name, required, type, pattern, minLength, maxLength, min, max, enum, default }, ...] }
//
// Per-row: produce { valid: bool, sanitized: {...}, errors: [...] }.
// Per-row errors are caught and reported, never thrown. A single bad row
// does not break the batch.
//
// ReDoS protection: VALIDATION_SCHEMA is operator-controlled (env var, not user-supplied).
// We still cap regex pattern length and reject patterns containing common catastrophic-
// backtracking shapes ((a+)+, (a|a)*, nested quantifiers) before compiling. Compilation
// failure or refusal returns one PATTERN_INVALID error per row, never a thrown crash.

const schemaRaw = $env.VALIDATION_SCHEMA || '{"columns":[]}';
let schema;
try { schema = JSON.parse(schemaRaw); }
catch (e) { throw new Error('VALIDATION_SCHEMA env is not valid JSON: ' + e.message); }

const columns = Array.isArray(schema.columns) ? schema.columns : [];
const MAX_PATTERN_LEN = 200;
// Refuse common catastrophic-backtracking shapes before compile.
// This is a heuristic, not a complete defense; the env-var-only contract is the primary mitigation.
const REDOS_HINT_RE = /(\([^)]*[+*][^)]*\))[+*]|(\([^)]*\|[^)]*\))[+*]/;

const compileSafePattern = (raw) => {
  if (typeof raw !== 'string' || raw.length === 0) return { error: 'pattern is empty' };
  if (raw.length > MAX_PATTERN_LEN) return { error: 'pattern length exceeds ' + MAX_PATTERN_LEN + ' chars' };
  if (REDOS_HINT_RE.test(raw)) return { error: 'pattern matches a known catastrophic-backtracking shape' };
  try { return { regex: new RegExp(raw) }; }
  catch (e) { return { error: 'pattern compile failed: ' + e.message }; }
};

// Pre-compile all column patterns once so we do not pay the cost per row.
const compiledPatterns = {};
for (const col of columns) {
  if (col && col.pattern) compiledPatterns[col.name] = compileSafePattern(col.pattern);
}

const sanitizeString = (v) => {
  let s = String(v == null ? '' : v);
  s = s.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, ''); // strip control chars
  s = s.trim().replace(/\s+/g, ' ');
  return s;
};

const checkRow = (raw, rowNumber) => {
  const sanitized = {};
  const errors = [];
  for (const col of columns) {
    const name = col.name;
    let val = raw[name];
    if ((val == null || val === '') && col.default != null) val = col.default;
    if ((val == null || val === '') && col.required) {
      errors.push({ field: name, code: 'REQUIRED', message: 'missing required value' });
      continue;
    }
    if (val == null || val === '') { sanitized[name] = null; continue; }

    // Type coercion
    if (col.type === 'integer') {
      const n = parseInt(val, 10);
      if (!Number.isFinite(n)) { errors.push({ field: name, code: 'TYPE', message: 'expected integer' }); continue; }
      if (col.min != null && n < col.min) errors.push({ field: name, code: 'MIN', message: 'below min ' + col.min });
      if (col.max != null && n > col.max) errors.push({ field: name, code: 'MAX', message: 'above max ' + col.max });
      sanitized[name] = n;
    } else if (col.type === 'number') {
      const n = parseFloat(val);
      if (!Number.isFinite(n)) { errors.push({ field: name, code: 'TYPE', message: 'expected number' }); continue; }
      if (col.min != null && n < col.min) errors.push({ field: name, code: 'MIN', message: 'below min ' + col.min });
      if (col.max != null && n > col.max) errors.push({ field: name, code: 'MAX', message: 'above max ' + col.max });
      sanitized[name] = n;
    } else if (col.type === 'boolean') {
      const sLower = String(val).trim().toLowerCase();
      if (['true', 'yes', 'y', '1'].includes(sLower)) sanitized[name] = true;
      else if (['false', 'no', 'n', '0'].includes(sLower)) sanitized[name] = false;
      else errors.push({ field: name, code: 'TYPE', message: 'expected boolean' });
    } else {
      // string default
      const s = sanitizeString(val);
      if (col.minLength != null && s.length < col.minLength) errors.push({ field: name, code: 'MIN_LEN', message: 'below minLength ' + col.minLength });
      if (col.maxLength != null && s.length > col.maxLength) errors.push({ field: name, code: 'MAX_LEN', message: 'above maxLength ' + col.maxLength });
      if (col.enum && Array.isArray(col.enum) && !col.enum.includes(s)) errors.push({ field: name, code: 'ENUM', message: 'not in allowed enum' });
      if (col.pattern) {
        const compiled = compiledPatterns[name];
        if (compiled && compiled.regex) {
          if (!compiled.regex.test(s)) errors.push({ field: name, code: 'PATTERN', message: 'does not match required pattern' });
        } else {
          errors.push({ field: name, code: 'PATTERN_INVALID', message: 'schema pattern rejected: ' + (compiled && compiled.error || 'unknown') });
        }
      }
      sanitized[name] = s;
    }
  }
  return { rowNumber, valid: errors.length === 0, sanitized, errors };
};

return $input.all().map(item => {
  const j = item.json || {};
  try {
    const result = checkRow(j.raw || {}, j.rowNumber);
    return { json: result };
  } catch (e) {
    return { json: { rowNumber: j.rowNumber, valid: false, sanitized: null, errors: [{ field: '_row', code: 'PARSE_ERROR', message: e.message }] } };
  }
});

// Aggregate per-row results into a structured report.

const valid = [];
const invalid = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.valid) valid.push({ row: j.rowNumber, data: j.sanitized });
  else invalid.push({ row: j.rowNumber, errors: j.errors });
}

const summary = {
  total: valid.length + invalid.length,
  validCount: valid.length,
  invalidCount: invalid.length,
  validPct: (valid.length + invalid.length) > 0 ? Math.round((valid.length / (valid.length + invalid.length)) * 1000) / 10 : 0,
  generatedAt: new Date().toISOString(),
};

return [{ json: { summary, valid, invalid } }];

// Fallback when the Slack notification fails. Still respond OK to the client.

const input = $input.first();
const err = (input.json && input.json.error) || input.error || {};
const report = ($('Build Report').first() && $('Build Report').first().json) || { summary: {} };

return [{
  json: {
    ...report,
    slackError: { message: err.message || 'unknown error', name: err.name || 'SlackError' },
  },
}];
